package gis
import("sort";"strings";"time")
type VerificationResult struct{PlanID string `json:"plan_id"`;Status string `json:"status"`;Recovered []string `json:"recovered,omitempty"`;StillAffected []string `json:"still_affected,omitempty"`;VerifiedAt time.Time `json:"verified_at"`}
func VerifyRecovery(plan RecoveryPlan,observed map[string]string)VerificationResult{r:=VerificationResult{PlanID:strings.TrimSpace(plan.ID),Status:"verified",VerifiedAt:time.Now().UTC()};if r.PlanID==""{r.Status="invalid";return r};seenRecovered:=map[string]struct{}{};seenAffected:=map[string]struct{}{};for _,step:=range plan.Steps{target:=strings.TrimSpace(step.Target);if target==""{continue};state:=strings.ToLower(strings.TrimSpace(observed[target]));if state=="healthy"{if _,ok:=seenRecovered[target];!ok{r.Recovered=append(r.Recovered,target);seenRecovered[target]=struct{}{}}}else{if _,ok:=seenAffected[target];!ok{r.StillAffected=append(r.StillAffected,target);seenAffected[target]=struct{}{}}}};sort.Strings(r.Recovered);sort.Strings(r.StillAffected);if len(r.StillAffected)>0{r.Status="partial"};return r}
